// src/services/quota-manager.ts
import fs3 from "fs";
import path3 from "path";
var SECURITY_CATEGORIES = ["unknown", "mismatch", "corrupted", "disguised"];
function normalizeCategory(category) {
  if (!SECURITY_CATEGORIES.includes(category)) {
    return category;
  }
  return "other";
}
var DEFAULT_USAGE_STATS = {
  usedFiles: 0,
  usedStorage: 0,
  byCategory: {
    image: { count: 0, storage: 0 },
    audio: { count: 0, storage: 0 },
    video: { count: 0, storage: 0 },
    document: { count: 0, storage: 0 },
    archive: { count: 0, storage: 0 },
    application: { count: 0, storage: 0 },
    font: { count: 0, storage: 0 },
    model: { count: 0, storage: 0 },
    data: { count: 0, storage: 0 },
    other: { count: 0, storage: 0 }
  }
};

class QuotaManager {
  usageCache = new Map;
  getDataDir() {
    return config2.getServer().dataDir;
  }
  async getUserQuota(userId) {
    const quotaConfig = config2.getQuota();
    const usage = await this.getUsage(userId);
    let maxFiles;
    let maxStorage;
    if (userId && quotaConfig.userOverrides[userId]) {
      maxFiles = quotaConfig.userOverrides[userId].maxFiles || quotaConfig.defaults.maxFiles;
      maxStorage = quotaConfig.userOverrides[userId].maxStorageBytes || quotaConfig.defaults.maxStorageBytes;
    } else {
      maxFiles = quotaConfig.defaults.maxFiles;
      maxStorage = quotaConfig.defaults.maxStorageBytes;
    }
    return {
      maxFiles,
      maxStorage,
      usedFiles: usage.usedFiles,
      usedStorage: usage.usedStorage,
      remainingFiles: maxFiles - usage.usedFiles,
      remainingStorage: maxStorage - usage.usedStorage,
      usagePercentage: maxFiles > 0 ? usage.usedFiles / maxFiles * 100 : 0
    };
  }
  async getGlobalQuota() {
    const quotaConfig = config2.getQuota();
    const usage = await this.getUsage(null);
    return {
      maxFiles: quotaConfig.global.maxTotalFiles,
      maxStorage: quotaConfig.global.maxTotalStorageBytes,
      usedFiles: usage.usedFiles,
      usedStorage: usage.usedStorage,
      byCategory: usage.byCategory
    };
  }
  async checkQuota(userId, fileSize) {
    const quota = await this.getUserQuota(userId);
    if (fileSize > quota.remainingStorage) {
      return {
        allowed: false,
        reason: `Would exceed storage limit (${quota.remainingStorage} bytes remaining)`
      };
    }
    if (quota.remainingFiles <= 0) {
      return {
        allowed: false,
        reason: `Would exceed file count limit (${quota.remainingFiles} slots remaining)`
      };
    }
    const globalQuota = await this.getGlobalQuota();
    if (fileSize > globalQuota.maxStorage - globalQuota.usedStorage) {
      return {
        allowed: false,
        reason: "Would exceed global storage limit"
      };
    }
    if (globalQuota.usedFiles >= globalQuota.maxFiles) {
      return {
        allowed: false,
        reason: "Would exceed global file count limit"
      };
    }
    return { allowed: true };
  }
  async reserveQuota(userId, fileSize, category) {
    const normalizedCategory = normalizeCategory(category);
    const check2 = await this.checkQuota(userId, fileSize);
    if (!check2.allowed)
      return false;
    const userKey = userId || "_anonymous";
    const userUsage = await this.getUsage(userId);
    userUsage.usedFiles++;
    userUsage.usedStorage += fileSize;
    userUsage.byCategory[normalizedCategory].count++;
    userUsage.byCategory[normalizedCategory].storage += fileSize;
    await this.saveUsage(userKey, userUsage);
    const globalUsage = await this.getUsage(null);
    globalUsage.usedFiles++;
    globalUsage.usedStorage += fileSize;
    globalUsage.byCategory[normalizedCategory].count++;
    globalUsage.byCategory[normalizedCategory].storage += fileSize;
    await this.saveUsage("_global", globalUsage);
    return true;
  }
  async releaseQuota(userId, fileSize, category) {
    const normalizedCategory = normalizeCategory(category);
    const userKey = userId || "_anonymous";
    const userUsage = await this.getUsage(userId);
    userUsage.usedFiles = Math.max(0, userUsage.usedFiles - 1);
    userUsage.usedStorage = Math.max(0, userUsage.usedStorage - fileSize);
    userUsage.byCategory[normalizedCategory].count = Math.max(0, userUsage.byCategory[normalizedCategory].count - 1);
    userUsage.byCategory[normalizedCategory].storage = Math.max(0, userUsage.byCategory[normalizedCategory].storage - fileSize);
    await this.saveUsage(userKey, userUsage);
    const globalUsage = await this.getUsage(null);
    globalUsage.usedFiles = Math.max(0, globalUsage.usedFiles - 1);
    globalUsage.usedStorage = Math.max(0, globalUsage.usedStorage - fileSize);
    globalUsage.byCategory[normalizedCategory].count = Math.max(0, globalUsage.byCategory[normalizedCategory].count - 1);
    globalUsage.byCategory[normalizedCategory].storage = Math.max(0, globalUsage.byCategory[normalizedCategory].storage - fileSize);
    await this.saveUsage("_global", globalUsage);
  }
  async getUsage(userId) {
    const key = userId || "_global";
    if (this.usageCache.has(key)) {
      return this.usageCache.get(key);
    }
    const dataDir = this.getDataDir();
    const usagePath = path3.join(dataDir, `usage-${key}.json`);
    try {
      if (fs3.existsSync(usagePath)) {
        const data = JSON.parse(fs3.readFileSync(usagePath, "utf-8"));
        this.usageCache.set(key, data);
        return data;
      }
    } catch (error48) {
      console.warn(`Error loading usage for ${key}:`, error48);
    }
    return { ...DEFAULT_USAGE_STATS };
  }
  async saveUsage(key, usage) {
    const dataDir = this.getDataDir();
    if (!fs3.existsSync(dataDir)) {
      fs3.mkdirSync(dataDir, { recursive: true });
    }
    const usagePath = path3.join(dataDir, `usage-${key}.json`);
    fs3.writeFileSync(usagePath, JSON.stringify(usage, null, 2));
    this.usageCache.set(key, usage);
  }
  clearCache() {
    this.usageCache.clear();
  }
}
var quotaManager = new QuotaManager;

