class ClientFactory {
  filterServices;
  constructor(filterServices) {
    this.filterServices = filterServices;
  }
  createClient(nameOrId) {
    return {
      get: async (path5, options) => this.fetchInternal(nameOrId, path5, { ...options, method: "GET" }),
      post: async (path5, options) => this.fetchInternal(nameOrId, path5, { ...options, method: "POST" }),
      put: async (path5, options) => this.fetchInternal(nameOrId, path5, { ...options, method: "PUT" }),
      delete: async (path5, options) => this.fetchInternal(nameOrId, path5, { ...options, method: "DELETE" })
    };
  }
  async fetchInternal(nameOrId, path5, options) {
    let services = this.filterServices({ name: nameOrId });
    if (services.length === 0) {
      services = this.filterServices({ id: nameOrId });
    }
    if (services.length === 0) {
      throw new Error(`Service ${nameOrId} not found`);
    }
    const target = services[0];
    if (!target) {
      throw new Error(`Service ${nameOrId} not found`);
    }
    const url2 = `${target.schema}://${target.ip}:${target.port}${path5}`;
    return fetch(url2, options);
  }
}
function generateServiceId(name) {
  const random = crypto4.randomBytes(4).toString("hex");
  const hostname3 = os2.hostname().replace(/[^a-zA-Z0-9]/g, "-").substring(0, 8);
  const prefix = name ? `${name}-` : "service";
  return `${prefix}-${hostname3}-${random}`;
}

class Discovery extends EventEmitter3 {
  serviceInfo;
  port;
  options;
  registry;
  network;
  clientFactory;
  heartbeatTimer = null;
  checkOfflineTimer = null;
  processHooksSet = false;
  onProcessExit;
  constructor(serviceInfo, port, options = {}) {
    super();
    const serviceId = serviceInfo.id || generateServiceId(serviceInfo.name);
    this.serviceInfo = {
      id: serviceId,
      name: serviceInfo.name,
      version: serviceInfo.version,
      schema: serviceInfo.schema || "http"
    };
    this.port = port;
    this.options = {
      multicastAddress: options.multicastAddress || "239.255.255.250",
      multicastInterface: options.multicastInterface || "",
      multicastPort: options.multicastPort || 54321,
      heartbeatInterval: options.heartbeatInterval || 5000,
      offlineTimeout: options.offlineTimeout || 15000,
      setupHooks: options.setupHooks !== undefined ? options.setupHooks : true
    };
    this.registry = new Registry;
    this.network = new Network(this.serviceInfo, this.port, this.options);
    this.clientFactory = new ClientFactory(this.filter.bind(this));
    this.onProcessExit = () => {
      this.stop();
      process.exit();
    };
    this.setupEvents();
  }
  setupEvents() {
    this.registry.on("online", (service) => this.emit("online", service));
    this.registry.on("offline", (service) => this.emit("offline", service));
    this.network.on("error", (err) => this.emit("error", err));
    this.network.on("message", (msg, senderIp) => this.handleMessage(msg, senderIp));
  }
  async start() {
    await this.network.start();
    this.network.broadcastPresence("hello");
    this.startTimers();
    if (this.options.setupHooks && !this.processHooksSet) {
      this.setupProcessHooks();
    }
  }
  handleMessage(msg, senderIp) {
    if (!msg || !msg.service)
      return;
    if (msg.service.id === this.serviceInfo.id)
      return;
    if (msg.type === "goodbye") {
      this.registry.remove(msg.service.id);
      return;
    }
    const discoveredService = {
      ...msg.service,
      ip: senderIp,
      lastSeen: Date.now()
    };
    this.registry.update(msg.service.id, discoveredService);
    if (msg.type === "hello") {
      this.network.broadcastPresence("heartbeat");
    }
  }
  startTimers() {
    this.heartbeatTimer = setInterval(() => {
      this.network.broadcastPresence("heartbeat");
    }, this.options.heartbeatInterval);
    this.checkOfflineTimer = setInterval(() => {
      this.registry.checkOffline(this.options.offlineTimeout);
    }, 1000);
  }
  filter(criteria) {
    return this.registry.filter(criteria);
  }
  setupProcessHooks() {
    process.on("SIGINT", this.onProcessExit);
    process.on("SIGTERM", this.onProcessExit);
    this.processHooksSet = true;
  }
  removeProcessHooks() {
    if (this.processHooksSet) {
      process.removeListener("SIGINT", this.onProcessExit);
      process.removeListener("SIGTERM", this.onProcessExit);
      this.processHooksSet = false;
    }
  }
  stop() {
    this.network.broadcastPresence("goodbye");
    if (this.heartbeatTimer)
      clearInterval(this.heartbeatTimer);
    if (this.checkOfflineTimer)
      clearInterval(this.checkOfflineTimer);
    if (this.options.setupHooks) {
      this.removeProcessHooks();
    }
    this.network.stop();
  }
  createClient(nameOrId) {
    return this.clientFactory.createClient(nameOrId);
  }
  getInternalRegistry() {
    return this.registry;
  }
  getServiceId() {
    return this.serviceInfo.id;
  }
}

// src/discover/init.ts
function getDiscoveryConfig(env = process.env) {
  return {
    enabled: env.DISCOVERY_ENABLED === undefined ? true : env.DISCOVERY_ENABLED.toLowerCase() === "true",
    serviceName: env.DISCOVERY_SERVICE_NAME || "media-upload-api",
    serviceVersion: env.DISCOVERY_SERVICE_VERSION || "1.0.0",
    multicastAddress: env.DISCOVERY_MULTICAST_ADDRESS || "239.255.255.250",
    multicastPort: parseInt(env.DISCOVERY_MULTICAST_PORT || "54321", 10),
    heartbeatInterval: parseInt(env.DISCOVERY_HEARTBEAT_INTERVAL || "5000", 10),
    offlineTimeout: parseInt(env.DISCOVERY_OFFLINE_TIMEOUT || "15000", 10),
    setupHooks: env.DISCOVERY_SETUP_HOOKS !== undefined ? env.DISCOVERY_SETUP_HOOKS.toLowerCase() === "true" : true
  };
}
async function initDiscovery(port, config3) {
  const discoveryConfig = config3 || getDiscoveryConfig();
  if (!discoveryConfig.enabled) {
    console.log("[Discovery] Service discovery is disabled (DISCOVERY_ENABLED=false)");
    return null;
  }
  const discovery = new Discovery({
    name: discoveryConfig.serviceName,
    version: discoveryConfig.serviceVersion,
    schema: "http"
  }, port, {
    multicastAddress: discoveryConfig.multicastAddress,
    multicastPort: discoveryConfig.multicastPort,
    heartbeatInterval: discoveryConfig.heartbeatInterval,
    offlineTimeout: discoveryConfig.offlineTimeout,
    setupHooks: discoveryConfig.setupHooks
  });
  discovery.on("online", (service) => {
    console.log(`[Discovery] Service online: ${service.name} (${service.id}) at ${service.ip}:${service.port}`);
  });
  discovery.on("offline", (service) => {
    console.log(`[Discovery] Service offline: ${service.name} (${service.id})`);
  });
  discovery.on("error", (err) => {
    console.error("[Discovery] Error:", err.message);
  });
  try {
    await discovery.start();
    console.log(`[Discovery] Service discovery started (service: ${discoveryConfig.serviceName}, port: ${discoveryConfig.multicastPort})`);
    return discovery;
  } catch (error48) {
    console.warn("[Discovery] Failed to start service discovery:", error48);
    return null;
  }
}

// src/server.ts
function startServer(options) {
  const serverConfig = loadConfig();
  const port = options?.port ?? serverConfig.port;
  const app2 = createApp();
  io.on("connection", (socket) => {
    console.log(`Client connected: ${socket.id}`);
    socket.on("disconnect", () => {
      console.log(`Client disconnected: ${socket.id}`);
    });
  });
  app2.get("/ws", upgradeWebSocket((c) => {
    return {
      onOpen: (event, ws) => {
        io.handleOpen(ws.raw);
      },
      onMessage: (event, ws) => {
        io.handleMessage(ws.raw, event.data.toString());
      },
      onClose: (event, ws) => {
        io.handleClose(ws.raw, event.code, event.reason);
      },
      onError: (event, ws) => {
        console.error("WebSocket error:", event);
      }
    };
  }));
  let discoveryInstance = null;
  let server;
  try {
    server = Bun.serve({
      fetch: app2.fetch,
      port,
      websocket
    });
    const actualPort = server.port;
    console.log(`Server running on port ${actualPort}`);
    saveConfig({ port: actualPort });
    initDiscovery(actualPort).then((instance) => {
      discoveryInstance = instance;
    });
  } catch (error48) {
    server = Bun.serve({
      fetch: app2.fetch,
      port: 0,
      websocket
    });
    const actualPort = server.port;
    saveConfig({ port: actualPort });
    console.log(`Server running on random port ${actualPort}`);
    initDiscovery(actualPort).then((instance) => {
      discoveryInstance = instance;
    });
  }
  const shutdown = () => {
    console.log("Shutting down server...");
    if (discoveryInstance) {
      discoveryInstance.stop();
    }
    process.exit(0);
  };
  process.on("SIGINT", shutdown);
  process.on("SIGTERM", shutdown);
  return server;
}
